import getpass
from pathlib import Path

from wpctl.libs import config
from wpctl.utils.custom_logger import get_logger

logger = get_logger(__name__)

_SOURCE_LABELS = {
    "env": "環境変数",
    "project": "プロジェクト設定",
    "user": "ユーザー設定",
    "none": "未設定",
}


def run_set(
    site_url: str | None = None,
    user: str | None = None,
    app_password: str | None = None,
    scope: str = "project",
) -> Path:
    """認証情報を設定ファイルへ保存する。

    値が指定されなかった項目は対話的に入力を求める。

    Args:
        site_url: WordPressサイトURL
        user: WordPressユーザー名
        app_password: WordPressアプリケーションパスワード
        scope: 保存先（"project" または "user"）

    Returns:
        保存先の設定ファイルパス
    """
    if site_url is None:
        site_url = input("WP_SITE_URL: ").strip()
    if user is None:
        user = input("WP_USER: ").strip()
    if app_password is None:
        app_password = getpass.getpass("WP_APP_PASSWORD: ").strip()

    values = {
        "WP_SITE_URL": site_url,
        "WP_USER": user,
        "WP_APP_PASSWORD": app_password,
    }
    path = config.set_config(values, scope=scope)
    logger.info(f"認証情報を保存しました: {path}")
    return path


def _mask(value: str) -> str:
    """値をマスクして表示用文字列を返す（先頭2文字と末尾2文字のみ表示）。

    Args:
        value: マスク対象の値

    Returns:
        マスクされた文字列
    """
    if len(value) <= 4:
        return "*" * len(value)
    return f"{value[:2]}{'*' * (len(value) - 4)}{value[-2:]}"


def get_status() -> list[dict]:
    """認証情報の設定状況を取得する。

    Returns:
        設定キーごとの状態（name, source_label, masked）のリスト
    """
    statuses = []
    for key, (value, source) in config.resolve_all().items():
        statuses.append({
            "name": key,
            "source_label": _SOURCE_LABELS.get(source, source),
            "masked": _mask(value) if value else None,
        })
    return statuses
